parameters.jsCode:
const response = $json?.body ?? $json;

if (!response || response.success !== true) {
  const message =
    response?.error ||
    response?.message ||
    "Apps Script returned an unsuccessful or invalid response.";

  throw new Error(`Gmail automation failed: ${message}`);
}

return [
  {
    json: {
      success: true,
      message: response.message || "Gmail automation completed successfully.",
      processed: response.processed ?? response.emails_processed ?? 0,
      attachments_uploaded: response.attachments_uploaded ?? 0,
      skipped: response.skipped ?? 0,
      errors: response.errors ?? [],
      processed_at: new Date().toISOString(),
      apps_script_response: response
    }
  }
];

return $input.all().map(item => ({
  json: {
    status: "SUCCESS",
    message: item.json.message,
    emails_processed: item.json.processed,
    attachments_uploaded: item.json.attachments_uploaded,
    skipped: item.json.skipped,
    processed_at: item.json.processed_at,
    errors: item.json.errors
  }
}));
